// --- 子组件2: 右上角从中间展开的箭头 ---
function TopRightArrow() {
  const variants = {
    hidden: { scaleX: 0, opacity: 0 },
    visible: {
      scaleX: 1,
      opacity: 1,
      transition: {
        duration: 0.6,
        ease: [0.6, 0.01, -0.05, 0.95],
      },
    },
  };
  return (
    <motion.g style={{ transformOrigin: "center" }} variants={variants}>
      <path
        d="M 570 77.7 L 725 77.7" // Slightly shorter line to leave space for the arrow
        stroke="black"
        strokeWidth="1"
      />
      {/* Shorter and more square-cut arrow after adjustment */}
      <path
        d="M 572 75 L 567.5 77.7 L 572 80.4 Z" // Use Z to close and fill
        fill="black"
      />
      <path
        d="M 723 75 L 727.5 77.7 L 723 80.4 Z" // 使用 Z 闭合并填充
        fill="black"
      />
    </motion.g>
  );
}

// --- 动画化的路径组件 (可复用) ---
function AnimatingPath({
  linePath,
  headPath,
  lineDelay,
  headDelay,
  duration,
  color,
}: {
  linePath: string;
  headPath: string;
  lineDelay: number;
  headDelay: number;
  duration: number;
  color: string;
}) {
  const lineVariants = {
    hidden: { pathLength: 0 },
    visible: { pathLength: 1, transition: { delay: lineDelay, duration, ease: "easeInOut" } },
  };

  const headVariants = {
    hidden: { opacity: 0, scale: 0.3 },
    visible: { opacity: 1, scale: 1, transition: { delay: headDelay, duration: 0.3 } },
  };

  return (
    <g>
      <motion.path d={linePath} stroke={color} strokeWidth="1" fill="none" variants={lineVariants} />
      <motion.path
        d={headPath}
        fill={color} // 改为填充以实现实心方形裁剪感
        variants={headVariants}
      />
    </g>
  );
}

export default function Group() {
  // 动画时间线规划
  const step1_finish = 0.6;
  const step2_start = step1_finish - 0.1;
  const step2_duration = 0.7;
  const step3_start = step2_start + step2_duration / 2;
  const step3_duration = 0.7;

  return (
    <motion.g initial="hidden" animate="visible">
      {/* --- 第1步: 右上角 --- */}
      <TopRightArrow />
      <TopRightText />

      {/* --- 第2步 (同时进行) --- */}
      {/* 右下箭头 (橙色) */}
      <AnimatingPath
        // 线条终点 X 坐标 (570) 与箭头基座 X 坐标 (570) 完美对齐
        linePath="M 645 77 L 645 284 L 570 284"
        // 箭头更短，更方正
        headPath="M 570 281 L 566 284 L 570 287 Z"
        color="#FCA800"
        lineDelay={step2_start}
        headDelay={step2_start + step2_duration - 0.2}
        duration={step2_duration}
      />
      {/* 中间向下箭头 (黑色) */}
      <AnimatingPath
        // 线条终点 Y 坐标 (240) 与箭头基座 Y 坐标 (240) 完美对齐
        linePath="M 456.5 184 L 456.5 240"
        // 箭头更短，更方正
        headPath="M 453.5 240 L 456.5 244 L 459.5 240 Z"
        color="black"
        lineDelay={step2_start}
        headDelay={step2_start + step2_duration - 0.2}
        duration={step2_duration}
      />

      {/* --- 第3步 --- */}
      {/* 左下箭头 (橙色) */}
      <AnimatingPath
        // 线条终点 Y 坐标 (242) 与箭头基座 Y 坐标 (242) 完美对齐
        linePath="M 435 284 L 127.5 284 L 127.5 242"
        // 箭头更短，更方正
        headPath="M 124.5 242 L 127.5 238 L 130.5 242 Z"
        color="#FCA800"
        lineDelay={step3_start}
        headDelay={step3_start + step3_duration - 0.2}
        duration={step3_duration}
      />
    </motion.g>
  );
}
